import { API_BASE_URL } from './config.js';


// 取得目前選擇帳號資訊（含 simulation_date）
async function getCurrentAccount() {
	try {
		const res = await fetch(`${API_BASE_URL}/current-account`, { credentials: 'include' });
		if (!res.ok) return null;
		const data = await res.json();
		if (!data.ok) return null;
		return data.account;
	} catch (e) {
		return null;
	}
}

async function fetchAccountOverview(account) {
    console.log('fetchAccountOverview', account);
    if (!account) return null;
    let url;
    if (account.selected_account_type === 'history') {
        // simulation_date 必須存在
        if (!account.selected_account_simulation_date) return null;
        url = `${API_BASE_URL}/account_overview/history?account_id=${account.selected_account_id}&date=${encodeURIComponent(account.selected_account_simulation_date)}`;
    } else {
        url = `${API_BASE_URL}/account_overview/realtime?account_id=${account.selected_account_id}`;
    }
    try {
        const res = await fetch(url);
        if (!res.ok) throw new Error('API 請求失敗');
        const data = await res.json();
        return data;
    } catch (err) {
        console.error('帳戶概覽查詢失敗:', err);
        return null;
    }
}

function renderAccountOverview(data) {
	if (!data) return;
	// 標題不顯示日期
	const title = document.querySelector('h1.h3');
	if (title) title.textContent = '帳戶概覽';
	// 資產摘要
	const summary = [
		{ selector: 0, value: data.total_assets, prefix: '$' },
		{ selector: 1, value: data.cash_balance, prefix: '$' },
		{ selector: 2, value: data.market_value, prefix: '$' },
		{ selector: 3, value: data.total_profit_loss_rate, prefix: '', percent: true },
		{ selector: 4, value: data.today_profit_loss_rate, prefix: '', percent: true }
	];
	document.querySelectorAll('.summary-cards .card-box').forEach((box, i) => {
		const p = box.querySelector('p');
		if (!p) return;
		let val = summary[i]?.value;
		if (val === undefined || val === null) return;
		if (summary[i].percent) {
			p.textContent = val;
			p.className = (typeof val === 'string' && val.startsWith('-')) ? 'text-danger' : 'text-success';
		} else {
			p.textContent = summary[i].prefix + Number(val).toLocaleString();
			p.className = '';
		}
	});

	// 圓餅圖
	if (window.assetChart && typeof window.assetChart.destroy === 'function') {
		window.assetChart.destroy();
	}
	const ctx = document.getElementById('assetChart').getContext('2d');
	window.assetChart = new Chart(ctx, {
		type: 'doughnut',
		data: {
			labels: ['可用現金', '持股市值'],
			datasets: [{
				label: '資產分布',
				data: [data.cash_balance, data.market_value],
				backgroundColor: ['#36b9cc', '#4e73df']
			}]
		},
		options: {
			responsive: true,
			plugins: { legend: { position: 'bottom' } }
		}
	});

	// 持股明細表格
	const table = document.querySelector('.table-container table');
	const tbody = table.querySelector('tbody');
	tbody.innerHTML = '';
	if (Array.isArray(data.holdings)) {
		data.holdings.forEach(h => {
			const market_value = h.quantity * h.market_price;
			const profit_rate = h.avg_cost ? (((h.market_price - h.avg_cost) / h.avg_cost) * 100).toFixed(2) + '%' : 'N/A';
			const tr = document.createElement('tr');
			tr.innerHTML = `
				<td>${h.symbol}</td>
				<td>${h.name}</td>
				<td>${h.quantity}</td>
				<td>$${h.avg_cost}</td>
				<td>$${h.market_price}</td>
				<td>$${market_value}</td>
				<td class="${profit_rate.startsWith('-') ? 'text-danger' : 'text-success'}">${profit_rate}</td>
			`;
			tbody.appendChild(tr);
		});
	}
}

window.addEventListener('DOMContentLoaded', async () => {
	const account = await getCurrentAccount();
	if (!account) {
		// 未選擇帳號，顯示提示
		const main = document.querySelector('.container-fluid');
		if (main) {
			main.innerHTML = `<div class="alert alert-warning mt-5" role="alert" style="font-size:1.2rem;">尚未選擇帳號，請先至帳號選擇頁建立或選擇帳號。</div>`;
		}
		return;
	}
	const data = await fetchAccountOverview(account);
	renderAccountOverview(data);
});
